import React, { useEffect, useState } from "react";
import axios from "axios";
import AppShell from "./ui/AppShell";
import Panel from "./ui/Panel";
import StatCard from "./ui/StatCard";
import AlertBox from "./AlertBox";
import { FaClipboardList, FaPlusCircle, FaUsers } from "react-icons/fa";
import "./theme.css";

function AssignmentsTeacher() {
  const teacherId = localStorage.getItem("user_id");

  const [courses, setCourses] = useState([]);
  const [assignments, setAssignments] = useState([]);
  const [submissions, setSubmissions] = useState([]);
  const [selectedCourse, setSelectedCourse] = useState("");
  const [selectedAssignment, setSelectedAssignment] = useState("");
  const [alert, setAlert] = useState(null);

  const [form, setForm] = useState({
    course_id: "",
    title: "",
    description: "",
    due_date: ""
  });

  useEffect(() => {
    loadCourses();
  }, []);

  const loadCourses = async () => {
    const res = await axios.get("http://127.0.0.1:8000/courses");
    const all = res.data.courses || [];
    setCourses(all.filter((c) => String(c.teacher_id) === String(teacherId)));
  };

  const loadAssignments = async (courseId) => {
    const res = await axios.get(`http://127.0.0.1:8000/assignments/${courseId}`);
    setAssignments(res.data.assignments || []);
  };

  const loadSubmissions = async (assignmentId) => {
    const res = await axios.get(`http://127.0.0.1:8000/assignment-submissions/${assignmentId}`);
    setSubmissions(res.data.submissions || []);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const payload = {
        course_id: Number(form.course_id),
        teacher_id: Number(teacherId),
        title: form.title,
        description: form.description,
        due_date: form.due_date   // IMPORTANT: string "YYYY-MM-DD"
      };

      console.log("Sending:", payload); // DEBUG

      const res = await axios.post(
        "http://127.0.0.1:8000/create-assignment",
        payload
      );

      setAlert({ message: res.data.message, type: "success" });

    } catch (err) {
  console.error("ERROR FULL:", err.response?.data);
  console.error("DETAIL:", err.response?.data?.detail);
  setAlert({ message: "Assignment creation failed", type: "error" });
}
  };

  return (
    <AppShell
      title="Assignments Panel"
      subtitle="Create assignments and review student submissions professionally."
    >
      {alert && <AlertBox message={alert.message} type={alert.type} onClose={() => setAlert(null)} />}

      <div className="page-grid-3" style={{ marginBottom: "20px" }}>
        <StatCard icon={<FaClipboardList />} label="Assignments" value={assignments.length} hint="Current assignment count" />
        <StatCard icon={<FaUsers />} label="Submissions" value={submissions.length} hint="Student submission records" />
        <StatCard icon={<FaPlusCircle />} label="Teacher Mode" value="Active" hint="Assignment creation enabled" />
      </div>

      <div className="page-grid-2">
        <Panel title="Create Assignment">
          <form onSubmit={handleSubmit}>
            <select
              className="select"
              name="course_id"
              value={form.course_id}
              onChange={(e) => {
                setForm({ ...form, course_id: e.target.value });
                setSelectedCourse(e.target.value);
                if (e.target.value) loadAssignments(e.target.value);
              }}
            >
              <option value="">Select Course</option>
              {courses.map((c) => (
                <option key={c.id} value={c.id}>
                  {c.title}
                </option>
              ))}
            </select>

            <input
              className="input"
              name="title"
              placeholder="Assignment Title"
              value={form.title}
              onChange={(e) => setForm({ ...form, title: e.target.value })}
            />

            <textarea
              className="textarea"
              name="description"
              placeholder="Question / Description"
              value={form.description}
              onChange={(e) => setForm({ ...form, description: e.target.value })}
            />

            <input
              className="input"
              type="date"
              name="due_date"
              value={form.due_date}
              onChange={(e) => setForm({ ...form, due_date: e.target.value })}
            />

            <button className="btn btn-primary">Create Assignment</button>
          </form>
        </Panel>

        <Panel title="Assignments List">
          <select
            className="select"
            value={selectedAssignment}
            onChange={(e) => {
              setSelectedAssignment(e.target.value);
              if (e.target.value) loadSubmissions(e.target.value);
            }}
          >
            <option value="">Select Assignment</option>
            {assignments.map((a) => (
              <option key={a.id} value={a.id}>
                {a.title}
              </option>
            ))}
          </select>

          {assignments.length === 0 ? (
            <p className="muted">No assignments found.</p>
          ) : (
            assignments.map((a) => (
              <div className="list-card" key={a.id}>
                <h4 style={{ marginTop: 0 }}>{a.title}</h4>
                <div className="muted">{a.description}</div>
                <div className="muted" style={{ marginTop: "8px" }}>
                  Due: {a.due_date}
                </div>
              </div>
            ))
          )}
        </Panel>
      </div>

      <div style={{ marginTop: "18px" }}>
        <Panel title="Student Submissions">
          {submissions.length === 0 ? (
            <p className="muted">No submissions yet.</p>
          ) : (
            submissions.map((s) => (
              <div className="list-card" key={s.id}>
                <div style={{ fontWeight: 700 }}>{s.student_name}</div>
                <div className="muted" style={{ marginTop: "6px" }}>
                  Status: {s.status}
                </div>
                {s.file_url ? (
                  <div style={{ marginTop: "10px" }}>
                    <a
                      className="btn btn-info"
                      href={`http://127.0.0.1:8000${s.file_url}`}
                      target="_blank"
                    >
                      View File
                    </a>
                  </div>
                ) : null}
              </div>
            ))
          )}
        </Panel>
      </div>
    </AppShell>
  );
}

export default AssignmentsTeacher;
